package ktanesolver.module.modded.regular.orangearrows;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class OrangeArrowsSolverTest{@Test void invertsEveryFourthArrowAndPersistsAllStages(){OrangeArrowsSolver solver=new OrangeArrowsSolver();ModuleEntity module=new ModuleEntity();OrangeArrowsOutput one=solve(solver,module,1,List.of("up","right","down","left","up"));assertThat(one.pressSequence()).containsExactly("up","right","down","right","up");solve(solver,module,2,List.of("left","left","left","left","left"));OrangeArrowsOutput three=solve(solver,module,3,List.of("down","down","down","down","down"));assertThat(three.command()).isEqualTo("down down down up down");assertThat(module.getState().get("orangeArrowsSequences")).isEqualTo(List.of(List.of("up","right","down","left","up"),List.of("left","left","left","left","left"),List.of("down","down","down","down","down")));}@SuppressWarnings("unchecked")private static OrangeArrowsOutput solve(OrangeArrowsSolver s,ModuleEntity m,int st,List<String>seq){return((SolveSuccess<OrangeArrowsOutput>)s.solve(new RoundEntity(),new BombEntity(),m,new OrangeArrowsInput(st,seq))).output();}}
